// ============================================================
// Responsive image helper – Mob Atidol
// Maps an original image path (e.g. './images/kitchen/IMG_KITCHEN_1.png')
// to its optimised WebP variants generated by scripts/optimize-images.mjs.
// Falls back to the original file if no optimised version exists.
// ============================================================
import { IMAGE_MANIFEST } from './imageManifest'

export interface ResponsiveImageAttrs {
  src: string
  srcSet?: string
  sizes?: string
  width?: number
  height?: number
}

/** Common `sizes` hints, matching the layout breakpoints used in the CSS. */
export const SIZES = {
  fullWidth: '100vw',
  card: '(min-width: 1024px) 33vw, (min-width: 640px) 50vw, 100vw',
  gallery3: '(min-width: 640px) 33vw, 50vw',
  gallery4: '(min-width: 1024px) 25vw, (min-width: 640px) 33vw, 50vw',
  carousel: '(min-width: 1200px) 1200px, 100vw',
  thumb: '160px',
  lightbox: '(min-width: 1220px) 1100px, 90vw',
  aboutMain: '(min-width: 1024px) 35vw, 80vw',
  aboutSecond: '(min-width: 1024px) 25vw, 60vw',
} as const

const toKey = (src: string) => src.replace(/^\.?\//, '')

const variantUrl = (key: string, width: number) =>
  `./${key.replace(/^images\//, 'images-optimized/').replace(/\.[^./]+$/, '')}-${width}.webp`

/**
 * Returns `<img>` attributes (src, srcSet, sizes, width, height) for an original image path.
 * `width`/`height` are the intrinsic dimensions so the browser can reserve space (no layout shift).
 */
export function responsiveImage(src: string, sizes: string, { withDimensions = true } = {}): ResponsiveImageAttrs {
  const key = toKey(src)
  const entry = IMAGE_MANIFEST[key]
  if (!entry) return { src }

  const { widths } = entry
  // Default `src` = middle variant – a sensible size for browsers ignoring srcset.
  const fallback = widths[Math.min(1, widths.length - 1)]
  return {
    src: variantUrl(key, fallback),
    srcSet: widths.map((w) => `${variantUrl(key, w)} ${w}w`).join(', '),
    sizes,
    ...(withDimensions ? { width: entry.w, height: entry.h } : {}),
  }
}
